# rust_utils — MCP server generated by mcp-forge
# Provides utility functions for number theory, text processing, and list operations. Enables tasks such as checking primality, calculating factorials, reversing strings, and summing lists.
#
# Auto-generated — edit as needed.
# IMPORTANT : ce serveur compile puis exécute des fonctions Rust.
#             Assurez-vous que 'rustc' est installé et accessible dans votre PATH.
#             Chaque appel d'outil recompile le pilote (source + appel) dans
#             un binaire temporaire, l'exécute, puis supprime les deux
#             fichiers temporaires — pas de cache de compilation entre appels.
# To run: python server.py
# To test: mcp dev server.py

from __future__ import annotations

import os
from contextvars import ContextVar

import json
import shutil
import subprocess
import tempfile

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("rust_utils")

_request_token: ContextVar[str] = ContextVar("_request_token", default="")

# Redéfinissable via variable d'environnement pour un déploiement hors de la
# machine où le serveur a été généré (le chemin par défaut ne fonctionnera
# que sur cette machine).
SCRIPT_SOURCE_DIR = os.environ.get("RUST_SOURCE_DIR", os.path.join(os.path.dirname(os.path.abspath(__file__)), "source"))


def _compiler_available() -> bool:
    return shutil.which("rustc") is not None


def _compile_and_run(script_file: str, call_expr: str) -> str:
    """Compile le driver (source + point d'entrée appelant `call_expr`) puis
    l'exécute. Logique commune à tous les outils de ce serveur — extraite ici
    pour éviter de la répéter dans chaque fonction `@mcp.tool` (répétition
    signalée par l'évaluateur qualité avant cette extraction)."""
    if not _compiler_available():
        return "Erreur : compilateur 'rustc' introuvable dans le PATH."

    source_path = os.path.join(SCRIPT_SOURCE_DIR, script_file)
    try:
        with open(source_path, encoding="utf-8") as f:
            source_code = f.read()
    except OSError as exc:
        return f"Erreur : impossible de lire {source_path} ({exc})"

    # Le fichier source est compilé en entier avec un point d'entrée ajouté
    # à la suite : les définitions du fichier original sont donc visibles
    # au moment de l'appel, sans dépendre d'un système de modules/paquets
    # (crate Cargo, module Fortran externe...) à mettre en place séparément.
    driver = source_code + "\n\nfn main() {\n    println!(\"{}\", " + call_expr + ");\n}\n"

    tmp_src = None
    tmp_bin = None
    # None tant qu'aucune tentative d'exécution n'a eu lieu (ex: la
    # compilation échoue avant) — distingue ce cas d'un vrai code de retour
    # 0, pour éviter un NameError si on y accédait sans ce garde-fou.
    run_result = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".rs", delete=False, encoding="utf-8"
        ) as tmp:
            tmp.write(driver)
            tmp_src = tmp.name
        tmp_bin = tmp_src + (".exe" if os.name == "nt" else ".out")

        compile_result = subprocess.run(
            ["rustc", tmp_src, "-o", tmp_bin],
            capture_output=True, text=True, timeout=30,
            # Voir server_codebase_scripting.py.j2 pour l'explication de ce
            # shell=True conditionnel (résolution .bat/.cmd sous Windows,
            # dangereux à activer sous POSIX avec une liste d'arguments).
            shell=(os.name == "nt"),
        )
        if compile_result.returncode != 0:
            return f"Erreur de compilation Rust : {compile_result.stderr.strip() or compile_result.stdout.strip()}"

        run_result = subprocess.run(
            [tmp_bin],
            capture_output=True, text=True, timeout=10,
            shell=(os.name == "nt"),
        )
    except subprocess.TimeoutExpired as exc:
        return f"Erreur Rust : timeout ({exc})"
    finally:
        for _p in (tmp_src, tmp_bin):
            if _p:
                try:
                    os.unlink(_p)
                except OSError:
                    pass

    if run_result is None:
        return f"Erreur Rust : exécution jamais lancée."
    if run_result.returncode != 0:
        return f"Erreur Rust : {run_result.stderr.strip() or run_result.stdout.strip()}"
    return run_result.stdout.strip()


def _to_literal(value: object) -> str:
    """Formate une valeur Python en littéral Rust valide."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        return json.dumps(value)
    if isinstance(value, (list, tuple)):
        return "&[" + ", ".join(_to_literal(v) for v in value) + "]"
    return json.dumps(value)

@mcp.tool(name="is_prime")
def is_prime(
    n: int,
) -> str:
    """Check if a given non-negative integer is a prime number. Use this when you need to verify the primality of a value for mathematical calculations or number theory tasks.
    Args:
        n: The non-negative integer to check for primality.
    Returns:
        Résultat de la fonction Rust.
    """
    call_args = ", ".join(_to_literal(v) for v in [n])
    call_expr = "is_prime(" + call_args + ")"
    return _compile_and_run("utils.rs", call_expr)

@mcp.tool(name="calculate_factorial")
def calculate_factorial(
    n: int,
) -> str:
    """Compute the factorial of a non-negative integer. Use this when you need to calculate the product of all positive integers up to n for combinatorial problems.
    Args:
        n: The non-negative integer for which to compute the factorial.
    Returns:
        Résultat de la fonction Rust.
    """
    call_args = ", ".join(_to_literal(v) for v in [n])
    call_expr = "factorial(" + call_args + ")"
    return _compile_and_run("utils.rs", call_expr)

@mcp.tool(name="reverse_string")
def reverse_string(
    s: str,
) -> str:
    """Reverse the characters in a given string. Use this when you need to flip the order of characters for string manipulation tasks.
    Args:
        s: The string to be reversed.
    Returns:
        Résultat de la fonction Rust.
    """
    call_args = ", ".join(_to_literal(v) for v in [s])
    call_expr = "reverse_string(" + call_args + ")"
    return _compile_and_run("utils.rs", call_expr)

@mcp.tool(name="sum_numbers")
def sum_numbers(
    numbers: list,
) -> str:
    """Calculate the sum of a list of floating-point numbers. Use this when you need to compute the total of a collection of numerical values.
    Args:
        numbers: The list of floating-point numbers to sum.
    Returns:
        Résultat de la fonction Rust.
    """
    call_args = ", ".join(_to_literal(v) for v in [numbers])
    call_expr = "sum_list(" + call_args + ")"
    return _compile_and_run("utils.rs", call_expr)


