    def _clean_codes() -> None:
        now = time.monotonic()
        expired = [k for k, v in _auth_codes.items() if now > v["expires_at"]]
        for k in expired:
            del _auth_codes[k]

    def _verify_pkce(code_verifier: str, code_challenge: str) -> bool:
        try:
            digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        except ValueError:
            return False
        computed = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
        return secrets.compare_digest(computed, code_challenge)

    def _login_page(error: str = "", **fields) -> HTMLResponse:
        error_block = f'<div class="err">{error}</div>' if error else ""
        html = _LOGIN_HTML.format(error_block=error_block, server_name=_SERVER_NAME, **fields)
        return HTMLResponse(html, status_code=401 if error else 200)

    def resource_metadata(_request: Request) -> JSONResponse:
        return JSONResponse({
            "resource": _MCP_SERVER_URL,
            "authorization_servers": [_MCP_SERVER_URL],
            "bearer_methods_supported": ["header", "query"],
        })

    def oauth_discovery(_request: Request) -> JSONResponse:
        return JSONResponse({
            "issuer": _MCP_SERVER_URL,
            "authorization_endpoint": f"{_MCP_SERVER_URL}/oauth/authorize",
            "token_endpoint": f"{_MCP_SERVER_URL}/oauth/token",
            "registration_endpoint": f"{_MCP_SERVER_URL}/oauth/register",
            "response_types_supported": ["code"],
            "grant_types_supported": ["authorization_code"],
            "code_challenge_methods_supported": ["S256"],
            "token_endpoint_auth_methods_supported": ["none"],
        })

    async def oauth_register(request: Request) -> JSONResponse:
        ip = request.client.host if request.client else "unknown"
        if not _check_rate_limit(ip):
            return JSONResponse({"error": "too_many_requests"}, status_code=429)
        try:
            body = await request.json()
        except Exception:
            body = {}
        return JSONResponse({
            "client_id": secrets.token_urlsafe(16),
            "client_id_issued_at": int(time.time()),
            "redirect_uris": body.get("redirect_uris", []),
            "grant_types": body.get("grant_types", ["authorization_code"]),
            "response_types": body.get("response_types", ["code"]),
            "token_endpoint_auth_method": "none",
        }, status_code=201)

    async def oauth_authorize(request: Request) -> Response:
        if request.method == "GET":
            p = dict(request.query_params)
            redirect_uri = p.get("redirect_uri", "")
            if not _validate_redirect_uri(redirect_uri):
                return JSONResponse(
                    {
                        "error": "invalid_request",
                        "error_description": (
                            "redirect_uri is not allowed. "
                            "Set OAUTH_ALLOWED_REDIRECT_HOSTS=<your-host> in production."
                        ),
                    },
                    status_code=400,
                )
            return _login_page(
                client_id=p.get("client_id", ""),
                redirect_uri=redirect_uri,
                state=p.get("state", ""),
                code_challenge=p.get("code_challenge", ""),
                code_challenge_method=p.get("code_challenge_method", "S256"),
            )

        ip = request.client.host if request.client else "unknown"
        if not _check_rate_limit(ip):
            return Response("Too many requests", status_code=429)

        form = await request.form()
        fields = dict(
            client_id=form.get("client_id", ""),
            redirect_uri=form.get("redirect_uri", ""),
            state=form.get("state", ""),
            code_challenge=form.get("code_challenge", ""),
            code_challenge_method=form.get("code_challenge_method", "S256"),
        )
        access_token = str(form.get("access_token", "")).strip()

        if not _validate_redirect_uri(fields["redirect_uri"]):
            return JSONResponse(
                {
                    "error": "invalid_request",
                    "error_description": (
                        "redirect_uri is not allowed. "
                        "Set OAUTH_ALLOWED_REDIRECT_HOSTS=<your-host> in production."
                    ),
                },
                status_code=400,
            )

        if not access_token:
            return _login_page(error="Access token requis.", **fields)
        if len(access_token) > 512:
            return _login_page(error="Token trop long.", **fields)
        if _MCP_SERVER_TOKEN and access_token != _MCP_SERVER_TOKEN:
            return _login_page(error="Access token invalide.", **fields)

        _clean_codes()
        code = secrets.token_urlsafe(32)
        _auth_codes[code] = {
            "token": access_token,
            "redirect_uri": fields["redirect_uri"],
            "code_challenge": fields["code_challenge"],
            "code_challenge_method": fields["code_challenge_method"],
            "expires_at": time.monotonic() + _AUTH_CODE_TTL,
        }
        sep = "&" if "?" in fields["redirect_uri"] else "?"
        location = (
            f"{fields['redirect_uri']}{sep}"
            f"code={urllib.parse.quote(code, safe='')}"
            f"&state={urllib.parse.quote(fields['state'], safe='')}"
        )
        return RedirectResponse(location, status_code=302)

    async def oauth_token(request: Request) -> JSONResponse:
        ip = request.client.host if request.client else "unknown"
        if not _check_rate_limit(ip):
            return JSONResponse({"error": "too_many_requests"}, status_code=429)

        form = await request.form()
        if form.get("grant_type") != "authorization_code":
            return JSONResponse({"error": "unsupported_grant_type"}, status_code=400)

        code = str(form.get("code", ""))
        redirect_uri = str(form.get("redirect_uri", ""))
        code_verifier = str(form.get("code_verifier", ""))

        _clean_codes()
        entry = _auth_codes.pop(code, None)
        if not entry or time.monotonic() > entry["expires_at"]:
            return JSONResponse(
                {"error": "invalid_grant", "error_description": "Unknown or expired code"},
                status_code=400,
            )
        if entry["redirect_uri"] and entry["redirect_uri"] != redirect_uri:
            return JSONResponse(
                {"error": "invalid_grant", "error_description": "redirect_uri mismatch"},
                status_code=400,
            )
        if entry["code_challenge"] and entry["code_challenge_method"] == "S256":
            if not code_verifier or not _verify_pkce(code_verifier, entry["code_challenge"]):
                return JSONResponse(
                    {"error": "invalid_grant", "error_description": "PKCE verification failed"},
                    status_code=400,
                )
        return JSONResponse({
            "access_token": entry["token"],
            "token_type": "bearer",
            "expires_in": 3600,
        })

    sse_transport = SseServerTransport("/messages/")

    def root(_request: Request) -> Response:
        return Response(
            status_code=401,
            headers={
                "WWW-Authenticate": (
                    f'Bearer realm="{_SERVER_NAME}", '
                    f'resource_metadata="{_MCP_SERVER_URL}/.well-known/oauth-protected-resource"'
                )
            },
        )

    async def handle_sse(request: Request):
        token = _request_token.get()
        if _MCP_SERVER_TOKEN and token != _MCP_SERVER_TOKEN:
            return Response(
                status_code=401,
                headers={
                    "WWW-Authenticate": (
                        f'Bearer realm="{_SERVER_NAME}", '
                        f'resource_metadata="{_MCP_SERVER_URL}/.well-known/oauth-protected-resource"'
                    )
                },
            )
        async with sse_transport.connect_sse(
            request.scope, request.receive, request._send
        ) as streams:
            await mcp._mcp_server.run(
                streams[0],
                streams[1],
                mcp._mcp_server.create_initialization_options(),
            )

    class _TokenMiddleware:
        def __init__(self, app):
            self._app = app

        async def __call__(self, scope, receive, send):
            if scope["type"] in ("http", "websocket"):
                headers = dict(scope.get("headers", []))
                auth = headers.get(b"authorization", b"").decode()
                token = auth[7:].strip() if auth.lower().startswith("bearer ") else ""
                if not token:
                    qs = scope.get("query_string", b"").decode()
                    for part in qs.split("&"):
                        if part.startswith("token="):
                            token = part[6:]
                            break
                _request_token.set(token)
            await self._app(scope, receive, send)

    starlette_app = Starlette(
        routes=[
            Route("/", endpoint=root),
            Route("/sse", endpoint=handle_sse),
            Mount("/messages/", app=sse_transport.handle_post_message),
            Route("/.well-known/oauth-protected-resource", endpoint=resource_metadata),
            Route("/.well-known/oauth-authorization-server", endpoint=oauth_discovery),
            Route("/oauth/register", endpoint=oauth_register, methods=["POST"]),
            Route("/oauth/authorize", endpoint=oauth_authorize, methods=["GET", "POST"]),
            Route("/oauth/token", endpoint=oauth_token, methods=["POST"]),
        ]
    )
    starlette_app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"],
        allow_methods=["GET", "POST", "OPTIONS"],
        allow_headers=["Authorization", "Content-Type"],
        expose_headers=["WWW-Authenticate"],
    )

    uvicorn.run(_TokenMiddleware(starlette_app), host="0.0.0.0", port=8000)
